<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AppLayout from'../../../Layouts/AppLayout.vue';const props=defineProps({managedUser:Object});const editing=!!props.managedUser;const form=useForm({first_name:props.managedUser?.first_name||'',last_name:props.managedUser?.last_name||'',mobile:props.managedUser?.mobile||'',email:props.managedUser?.email||'',role:props.managedUser?.role||'STUDENT',is_active:props.managedUser?.is_active??true,password:'',password_confirmation:''});const submit=()=>editing?form.put(`/admin/users/${props.managedUser.id}`):form.post('/admin/users')</script>
<template><AppLayout><Head :title="editing?'ویرایش کاربر':'کاربر جدید'"/><section class="rounded-2xl border bg-white p-6"><h1 class="mb-6 text-xl font-bold">{{editing?'ویرایش کاربر':'ایجاد کاربر'}}</h1><form class="grid gap-4 md:grid-cols-2" @submit.prevent="submit"><div><label for="first-name">نام <span class="text-red-700">(الزامی)</span></label><input id="first-name" v-model="form.first_name" required><p class="text-sm text-red-600">{{form.errors.first_name}}</p></div><div><label for="last-name">نام خانوادگی <span class="text-red-700">(الزامی)</span></label><input id="last-name" v-model="form.last_name" required><p class="text-sm text-red-600">{{form.errors.last_name}}</p></div><div><label for="mobile">شماره موبایل <span class="text-red-700">(الزامی)</span></label><input id="mobile" v-model="form.mobile" dir="ltr" required><p class="text-sm text-red-600">{{form.errors.mobile}}</p></div><div><label for="email">ایمیل (اختیاری)</label><input id="email" v-model="form.email" type="email" dir="ltr"><p class="text-sm text-red-600">{{form.errors.email}}</p></div><div><label for="role">نقش</label><select id="role" v-model="form.role" :disabled="managedUser?.role==='ADMIN'"><option value="TEACHER">مدرس</option><option value="STUDENT">هنرجو</option><option v-if="managedUser?.role==='ADMIN'" value="ADMIN">مدیر</option></select></div><label class="flex items-center gap-2 self-end pb-2"><input v-model="form.is_active" type="checkbox" class="h-4 w-4"> حساب فعال باشد</label><div><label for="new-password">{{editing?'رمز جدید (اختیاری)':'رمز عبور'}}</label><input id="new-password" v-model="form.password" type="password" autocomplete="new-password" :required="!editing"><p class="text-sm text-red-600">{{form.errors.password}}</p></div><div><label for="password-confirmation">تکرار رمز عبور</label><input id="password-confirmation" v-model="form.password_confirmation" type="password" autocomplete="new-password" :required="!editing"></div><div class="flex gap-3 md:col-span-2"><button :disabled="form.processing" class="rounded-xl bg-teal-700 px-5 py-2.5 font-bold text-white disabled:opacity-50">{{form.processing?'در حال ذخیره…':'ذخیره'}}</button><Link href="/admin/users" class="rounded-xl border px-5 py-2.5">انصراف</Link></div></form></section></AppLayout></template>
